import ast, copy, hashlib, json, subprocess
from pathlib import Path
root=Path('/workspace');proposal=json.loads((root/'proposal.json').read_text())
runtime=json.loads(subprocess.check_output(['python3',str(root/'tools.py'),'resolve','run://r-001'],text=True))
workspace=json.loads(subprocess.check_output(['python3',str(root/'tools.py'),'resolve','workspace://w-001'],text=True))
def validate(value,schema,path='study'):
 t=schema.get('type')
 if t=='object':
  assert isinstance(value,dict),(path,'type')
  assert set(schema.get('required',[]))<=set(value),(path,'required')
  props=schema.get('properties',{})
  if schema.get('additionalProperties') is False: assert set(value)<=set(props),(path,'extra')
  for k,v in value.items():
   if k in props:validate(v,props[k],path+'.'+k)
 elif t=='array':
  assert isinstance(value,list),(path,'type')
  assert len(value)>=schema.get('minItems',0),(path,'minItems')
  for i,v in enumerate(value):validate(v,schema.get('items',{}),path+f'[{i}]')
